contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount <= address(c).balance);
        uint balBefore = address(c).balance;
        uint depBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint selfBefore = address(this).balance;
        c.withdraw(amount); if (__ESBMC_reverted()) return;
        assert(!false && address(c).balance == balBefore - amount && address(this).balance == selfBefore + amount && c.depositsCount() == depBefore);
    }
    receive() external payable {}
}

