// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount <= address(c).balance);
        uint balBefore = address(c).balance;
        uint256 depBefore;
        try c.depositsCount() returns (uint256 __r) { depBefore = __r; } catch { return; }
        uint selfBefore = address(this).balance;
        try c.withdraw(amount) {} catch { return; }
        assertTrue(!false && address(c).balance == balBefore - amount && address(this).balance == selfBefore + amount && c.depositsCount() == depBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
